ST.xhtml:p:
RTrigger1(CLK := g_biCalOffsetOpen);
RTrigger2(CLK := g_biCalOffsetClose);

IF RTrigger1.Q THEN
  nOffsetState := 1;
  g_boCalOffsetDone := FALSE;
  g_boCalAnalogDone := FALSE;
END_IF;

IF RTrigger2.Q THEN
  g_boCalOffsetDone := FALSE;
  g_boCalAnalogDone := FALSE;
END_IF;

nSensorValue := g_niSensorValue;

IF g_niSensorValue >= LREAL_TO_DINT(dSensorValue2) - 1000 THEN
  g_bSensorError := TRUE;
END_IF;

CASE nOffsetState OF
  0:
    nOffsetState := 0;
  1:
    nOffsetState := 2;
    dTemp1 := (dBafflePos1 - dBafflePos2)/(dSensorValue1 - dSensorValue2);
    dTemp2 := (dSensorValue1*dBafflePos2 - dSensorValue2*dBafflePos1)/(dSensorValue1 - dSensorValue2);
    g_dOffset := DINT_TO_LREAL(g_niSensorValue)*dTemp1 + dTemp2 - dSensorCompDis + g_dSlitLength;
    IF g_dOffset <= -5.0 THEN
      g_dOffset := -5.0;
    ELSIF g_dOffset > dBafflePos2 THEN
      g_dOffset := dBafflePos2;
    END_IF;
    g_foOffset := g_dOffset - g_dSlitLength/2.0;
    g_boCalAnalogDone := TRUE;  
  2:
    g_SensorAbs.Execute := TRUE;
    g_SensorAbs.Velocity := dBackVelocity;
    IF g_dOffset > 0.0 THEN
      g_SensorAbs.Position := Axis_Sensor.NCTOPLC.SETPOS + dBackDistance + g_dOffset;
    ELSE
      g_SensorAbs.Position := Axis_Sensor.NCTOPLC.SETPOS + dBackDistance;
    END_IF;
    IF g_fPartLenght < g_dZAvoidPartLength THEN
      IF g_dOffset > 0.0 THEN
        g_SensorAbs.Position := Axis_Sensor.NCTOPLC.SETPOS + dBackDistance + g_dOffset + 30.0;
      ELSE
        g_SensorAbs.Position := Axis_Sensor.NCTOPLC.SETPOS + dBackDistance + 30.0;
      END_IF;
    END_IF;
    IF g_SensorAbs.Done THEN
      g_SensorAbs.Execute := FALSE;
      g_boCalOffsetDone := TRUE;
      nOffsetState := 0;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nOffsetState := 20;
    END_IF;
    IF g_SensorAbs.CommandAborted OR g_SensorAbs.Error THEN
      g_SensorAbs.Execute := FALSE;
      g_boCalOffsetDone := FALSE;
      nOffsetState := 0;
    END_IF;
  20:
    g_SensorAbs.Execute := FALSE;
    g_SensorStop.Execute := TRUE;
    IF g_SensorStop.Done AND g_bPlcStartBuffer THEN
      g_SensorStop.Execute := FALSE;
      nOffsetState := 2;
    END_IF;
    IF g_SensorStop.CommandAborted OR g_SensorStop.Error THEN
      g_SensorStop.Execute := FALSE;
      nOffsetState := 0;
    END_IF;   
END_CASE;


IF g_bPlcResetBuffer THEN
  nOffsetState := 0;
  g_SensorAbs.Execute := FALSE;
  g_SensorStop.Execute := FALSE;
END_IF;
